-- Reviewed additions for supply_disclosures (migration 0072). Replaying preserves later reviews.
WITH sources(key, publisher, published, url) AS (VALUES
  ('wy', 'Google', '2026-11-05', 'https://blog.google/innovation-and-ai/infrastructure-and-cloud/global-network/wyoming-data-center/'),
  ('bkh', 'Black Hills · Q3 10-Q', '2026-11-05', 'https://www.sec.gov/Archives/edgar/data/1130464/000119312526449130/bkh-20260930.htm'),
  ('ora', 'Ormat · Q3 10-Q', '2026-11-05', 'https://www.sec.gov/Archives/edgar/data/1296445/000129644526000017/ora-20260930.htm'),
  ('fervo-nv', 'Google', '2025-05-13', 'https://blog.google/feed/nevada-clean-energy/'),
  ('fervo-ut', 'Fervo · Q3 10-Q', '2026-11-10', 'https://www.sec.gov/Archives/edgar/data/1853868/000162828026072482/frvo-20260930.htm'),
  ('dell', 'CrowdStrike', '2026-11-02', 'https://www.crowdstrike.com/en-us/press-releases/crowdstrike-dell-technologies-announce-integrated-ai-security-dell-ai-factory-nvidia/'),
  ('dt', 'Deutsche Telekom', '2026-06-09', 'https://www.telekom.com/en/newsroom/latest-updates/media-information/2026/06/data-sovereign-protection-for-europe'),
  ('panw', 'Palo Alto Networks', '2025-12-19', 'https://www.paloaltonetworks.com/company/press/2025/palo-alto-networks-and-google-cloud-forge-landmark-agreement-to-help-customers-securely-accelerate-cloud-and-ai-initiatives')
), facts(id, key, provider_key, provider_name, recipient_key, recipient_name, product, stage, detail, phrase, pathway) AS (VALUES
  ('wy-bloom-aep', 'wy', 'BE', 'Bloom Energy', 'AEP', 'American Electric Power', 'Fuel cells for the Cheyenne project', 'planned', 'Google named Bloom as the manufacturer for AEP’s planned 702 MW Wyoming project. The 702 MW is the project’s design capacity.', 'made in America by Bloom Energy', 'Cheyenne fuel-cell generation'),
  ('wy-aep-google', 'wy', 'AEP', 'American Electric Power', 'GOOGL', 'Google', 'Power from the Cheyenne fuel-cell project', 'contracted', 'Google disclosed a contract with AEP for a 702 MW fuel-cell development with carbon capture for its first Wyoming data center. Output was prospective at announcement.', 'contracted with AEP', 'Cheyenne fuel-cell generation'),
  ('wy-bkh-google', 'bkh', 'BKH', 'Black Hills', 'GOOGL', 'Google', 'Cheyenne grid-connected service', 'contracted', 'Black Hills reported agreements extending through December 2048. It expected up to 590 MW of grid-connected service and a late-2027 start to energy service. It reports third-party microgrid resources separately.', 'up to 590 MW of grid-connected energy service', NULL),
  ('nv-ora-nve', 'ora', 'ORA', 'Ormat Technologies', '@nv-energy', 'NV Energy', 'Geothermal portfolio power purchase agreement', 'contracted', 'Ormat signed for up to 150 MW of new Nevada capacity, with deliveries from 2028–2030 as projects reach commercial operation. Its Q3 filing expected regulatory approval in late 2026 or early 2027.', 'long-term geothermal portfolio PPA', 'Ormat Nevada geothermal portfolio'),
  ('nv-nve-google-ora', 'ora', '@nv-energy', 'NV Energy', 'GOOGL', 'Google', 'Clean Transition Tariff for the Ormat portfolio', 'contracted', 'Ormat identified Google’s data centers as the intended beneficiaries through NV Energy’s tariff. The supply arrangements required Nevada approval. The term extends 15 years beyond the final project’s commercial start.', 'related energy supply arrangements are subject to approval', 'Ormat Nevada geothermal portfolio'),
  ('nv-fervo-nve', 'fervo-nv', 'FRVO', 'Fervo Energy', '@nv-energy', 'NV Energy', 'Enhanced geothermal development for Nevada', 'contracted', 'Nevada approved the energy supply agreement in May 2025. Google named Fervo as developer of 115 MW of new geothermal capacity to be delivered by NV Energy.', 'Developed by Fervo Energy', 'Fervo Nevada tariff agreement'),
  ('nv-nve-google-fervo', 'fervo-nv', '@nv-energy', 'NV Energy', 'GOOGL', 'Google', 'Nevada tariff delivery for Fervo generation', 'contracted', 'Google identified the 115 MW agreement as supporting its Nevada data centers and cloud region through the local grid. The announcement establishes regulatory approval and intended delivery.', 'delivered by NV Energy', 'Fervo Nevada tariff agreement'),
  ('ut-fervo-google', 'fervo-ut', 'FRVO', 'Fervo Energy', 'GOOGL', 'Google', 'Cape Station geothermal energy products', 'contracted', 'Fervo’s project subsidiary signed a 15-year, 396 MW PPA with Google Energy in August 2026. Its Q3 filing expected four 99 MW tranches starting in 2028 in Utah.', 'four 99 MW sub-tranches', NULL),
  ('dell-falcon-distribution', 'dell', 'CRWD', 'CrowdStrike', 'DELL', 'Dell Technologies', 'Falcon security distribution channel', 'in_use', 'In November 2026 Dell’s AI Ecosystem Program offered CrowdStrike security alongside Dell AI infrastructure. Security is an optional purchase. The announcement gives no customer uptake or contract value.', 'purchase AI infrastructure and CrowdStrike security together', 'Dell AI Factory security offering'),
  ('dell-nvidia-accelerated', 'dell', 'NVDA', 'NVIDIA', 'DELL', 'Dell Technologies', 'Accelerated computing for Dell AI Factory', 'in_use', 'The November 2026 joint offering combines NVIDIA accelerated computing with Dell AI infrastructure. Participation in the AI Factory does not establish a purchase of its optional Falcon component.', 'NVIDIA accelerated computing', 'Dell AI Factory security offering'),
  ('dt-panw-cortex', 'dt', 'PANW', 'Palo Alto Networks', 'DTEGY', 'Deutsche Telekom', 'Cortex software for a managed security service', 'in_use', 'The two companies launched Sovereign Cortex with T Security in Europe in June 2026. Palo Alto Networks contributes the security platform and Deutsche Telekom operates the managed service.', 'Sovereign Cortex with T Security', 'European sovereign Cortex service'),
  ('dt-google-key-management', 'dt', 'GOOGL', 'Google Cloud', 'DTEGY', 'Deutsche Telekom', 'External key-management technology', 'in_use', 'At the June 2026 launch, Deutsche Telekom described using Google Cloud technology while retaining control of encryption for the same European managed service.', 'External Key Manager', 'European sovereign Cortex service'),
  ('panw-google-prisma', 'panw', 'GOOGL', 'Google Cloud', 'PANW', 'Palo Alto Networks', 'Cloud network for Prisma Access', 'in_use', 'In December 2025 Palo Alto Networks identified Google’s network as infrastructure for Prisma Access. This product is separate from the European Sovereign Cortex service.', 'Prisma Access runs on', NULL)
)
INSERT INTO public.supply_disclosures
  (id, provider_key, provider_name, recipient_key, recipient_name, product, stage, detail, source_phrase, publisher, source_date, reviewed_on, source_url, pathway)
SELECT 'issuer:' || f.id, f.provider_key, f.provider_name, f.recipient_key, f.recipient_name, f.product, f.stage, f.detail, f.phrase, s.publisher, s.published::date, DATE '2026-11-27', s.url, f.pathway
FROM facts f JOIN sources s USING (key)
ON CONFLICT (id) DO NOTHING;
